<?php
/**
 * Icons management class for AI Share & Summarize plugin
 *
 * Uses official brand SVG paths from Simple Icons (simpleicons.org) where available.
 * All icons use fill-based rendering with viewBox 0 0 24 24 for consistency.
 *
 * @package AiShareSummarize
 * @since 1.2.0
 */

// Prevent direct access.
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Class to handle icons for buttons
 */
class AyudaWP_AISS_Icons {

	/**
	 * Get SVG icon for a specific platform
	 *
	 * @param string $platform Platform identifier.
	 * @param int    $size     Icon size in pixels.
	 * @return string SVG icon HTML.
	 */
	public static function ayudawp_get_icon( $platform, $size = 16 ) {
		$icons = self::ayudawp_get_icons_data();

		if ( ! isset( $icons[ $platform ] ) ) {
			return '';
		}

		$icon_data = $icons[ $platform ];

		return sprintf(
			'<svg width="%d" height="%d" viewBox="0 0 24 24" fill="currentColor" role="img" class="ayudawp-icon ayudawp-icon-%s" aria-hidden="true">%s</svg>',
			$size,
			$size,
			esc_attr( $platform ),
			$icon_data
		);
	}

