	/**
	 * Get icon with wrapper for button
	 *
	 * @param string $platform Platform identifier.
	 * @param int    $size     Icon size.
	 * @return string Icon HTML with wrapper.
	 */
	public static function ayudawp_get_button_icon( $platform, $size = 16 ) {
		$icon = self::ayudawp_get_icon( $platform, $size );

		if ( empty( $icon ) ) {
			return '';
		}

		return '<span class="ayudawp-icon-wrapper">' . $icon . '</span>';
	}
}